for b, (l, r) in enumerate(blocks):
    for p in range(l, r):
        chars.append((b, p))
del chars[index]
out = []
for b, p in chars:
    if out and out[-1][0] == b and out[-1][2] == p:
        out[-1][2] = p + 1
    else:
        out.append([b, p, p + 1])
print(len(out))
for b, l, r in out:
    print(l, r)

