    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        String ref = st.nextToken();
        int m = Integer.parseInt(st.nextToken());
        List<int[]> blocks = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int l = Integer.parseInt(st.nextToken());
            int r = Integer.parseInt(st.nextToken());
            blocks.add(new int[]{l, r});
        }
        long index = Long.parseLong(st.nextToken());
        List<int[]> res = deleteFromCover(ref, blocks, index);
        StringBuilder sb = new StringBuilder();
        sb.append(res.size()).append("\n");
        for (int[] b : res) sb.append(b[0]).append(" ").append(b[1]).append("\n");
        System.out.print(sb);
    }
}
